.d-drone-demo{width:100%;min-height:555px;box-sizing:border-box;padding:20px clamp(5px,4vw,28px);background:#0a0a0b;color:#e9eeee;font-family:Roboto Mono,JetBrains Mono,monospace}.d-drone-demo>header{display:flex;justify-content:space-between;color:#5f5f5f;font:500 8px/1 ui-monospace,monospace;letter-spacing:.14em}.d-drone-readout{color:#ececec}.d-drone-stage{position:relative;height:430px;margin-top:13px;overflow:hidden;border:1px solid #323232;background:#121212}.d-drone-sky{position:absolute;inset:0 52% 0 0;overflow:hidden;background:linear-gradient(#1c1c1c,#1c1c1c 55%,#1c1c1c)}.d-drone-sky i{position:absolute;left:-15%;right:-15%;top:var(--horizon,68%);height:2px;background:#ececec;box-shadow:0 0 35px #ececec;transform:rotate(calc(var(--velocity,0)*-4deg));transition:top .08s linear}.d-drone-spectrum{position:absolute;left:0;right:0;top:var(--horizon,68%);height:45%;background:repeating-linear-gradient(90deg,#ececec1f 0 1px,transparent 1px 12px);transform:perspective(160px) rotateX(64deg);transform-origin:top}.d-drone-sky b{position:absolute;left:9%;top:12%;font:500 clamp(22px,4vw,42px)/.88 Roboto Mono,sans-serif;letter-spacing:-.07em}.d-drone-sky span{position:absolute;right:8%;bottom:8%;color:#8c8c8c;font:500 7px/1.4 ui-monospace,monospace;text-align:right}.d-drone-scroll{position:absolute;left:48%;right:0;top:0;bottom:0;overflow-y:auto;scroll-snap-type:y mandatory;scrollbar-width:thin;scrollbar-color:#5f5f5f #1c1c1c}.d-drone-scroll article{height:100%;box-sizing:border-box;padding:22% 13%;display:flex;flex-direction:column;justify-content:center;scroll-snap-align:start;border-bottom:1px solid #323232}.d-drone-scroll em{color:#ececec;font:500 7px/1 ui-monospace,monospace;font-style:normal}.d-drone-scroll h3{margin:14px 0 0;font:500 clamp(18px,3vw,32px)/1.05 Roboto Mono,sans-serif;letter-spacing:-.05em}.d-drone-stage>p{position:absolute;left:11px;bottom:9px;margin:0;color:#8c8c8c;font:500 6px/1 ui-monospace,monospace;pointer-events:none}.d-drone-demo footer{display:flex;justify-content:center;gap:5px;margin-top:10px}.d-drone-demo footer button{min-height:32px;padding:7px 10px;border:1px solid #5f5f5f;background:#1c1c1c;color:#8c8c8c;font:500 7px/1 ui-monospace,monospace;text-transform:uppercase;cursor:pointer}.d-drone-demo footer button:hover,.d-drone-demo footer button:focus-visible{background:#ececec;color:#121212;outline:none}.d-drone-status{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
/* Native 320px composition: geometry first, controls second. */
.d-drone-demo{position:relative;height:320px;min-height:0;padding:16px;box-sizing:border-box;overflow:hidden;background:#0a0a0b;color:#ececef}
.d-drone-demo>header,.d-drone-demo>[class$="-head"]{display:none}
.d-drone-stage{height:248px;min-height:0;margin:0;box-sizing:border-box;border:0;background:#0a0a0b}
.d-drone-demo [class$="-guide"],.d-drone-demo [class$="-note"],.d-drone-demo [class$="-spec"],.d-drone-demo [class$="-hud"],.d-drone-stage>p{display:none}
.d-drone-demo footer,.d-drone-demo>[class$="-foot"]{display:flex;justify-content:center;align-items:center;gap:6px;margin:10px 0 0}
.d-drone-demo footer button,.d-drone-demo>[class$="-foot"] button{min-height:28px;padding:6px 8px;border:1px solid #333;border-radius:0;background:#161619;color:#b8b8b8;font:500 9px/1.15 'Roboto Mono',monospace;letter-spacing:0}
.d-drone-demo footer button:hover,.d-drone-demo footer button:focus-visible,.d-drone-demo>[class$="-foot"] button:hover,.d-drone-demo>[class$="-foot"] button:focus-visible{background:#262626;color:#fa7319;border-color:#fa7319;outline:none}
.d-drone-demo>[class$="-foot"]>p{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
.d-drone-sky b{font-size:20px;line-height:1.1;left:8%;top:12%}.d-drone-scroll h3{font-size:20px;line-height:1.15}.d-drone-scroll article{padding:18px}.d-drone-sky i{box-shadow:none}.d-drone-sky span{display:none}
.d-drone-demo footer{flex-wrap:nowrap;gap:5px}.d-drone-demo footer>button{flex:0 1 auto;min-width:0;white-space:normal;min-height:28px}.d-drone-stage{height:240px}

/* Material and typography refinement: calm light, fine edges, purposeful type. */
.d-drone-demo{--demo-sans:Manrope,system-ui,sans-serif;--demo-serif:Newsreader,Georgia,serif;font-family:var(--demo-sans)}
.d-drone-demo button,.d-drone-demo footer button,.d-drone-demo>[class$="-foot"] button{font-family:var(--demo-sans);font-size:10px;font-weight:500;line-height:1.2;letter-spacing:.005em;text-transform:none}
.d-drone-demo footer button,.d-drone-demo>[class$="-foot"] button{border-color:#ffffff16;border-radius:4px;background:linear-gradient(180deg,#202225,#191b1e);color:#b7bdc3}
.d-drone-demo footer button:hover,.d-drone-demo>[class$="-foot"] button:hover{border-color:#fa73194d;color:#dddfe1;background:#262a2e}
.d-drone-demo footer button:focus-visible,.d-drone-demo>[class$="-foot"] button:focus-visible{outline:1px solid #fa7319a8;outline-offset:2px}
.d-drone-sky b{font:500 20px/1.05 var(--demo-sans);letter-spacing:-.035em}.d-drone-scroll h3{font:500 22px/1.14 var(--demo-sans);letter-spacing:-.035em}.d-drone-sky{background:linear-gradient(150deg,#22272b,#181c20)}

/* Composition redesign: native sizing, purposeful content and Inter UI. */
.d-drone-demo{font-family:Inter,system-ui,sans-serif;background:#111214;font-variant-numeric:tabular-nums}.d-drone-demo :where(*){font-family:Inter,system-ui,sans-serif!important;letter-spacing:normal!important;font-variant-numeric:tabular-nums}.d-drone-demo :where(code,pre,code *,pre *){font-family:ui-monospace,monospace!important}.d-drone-demo footer button,.d-drone-demo>[class$="-foot"] button{min-height:29px;padding:6px 10px;border:1px solid #a6bdcc15;border-radius:6px;background:#23303a;color:#a8becd;font:450 11px/1.25 Inter,system-ui,sans-serif;text-transform:none;white-space:nowrap}.d-drone-demo footer button:hover,.d-drone-demo>[class$="-foot"] button:hover{background:#344550;color:#d5e4ed;border-color:#a6bdcc27}.d-drone-demo footer button:focus-visible,.d-drone-demo>[class$="-foot"] button:focus-visible{outline:2px solid #9db6c7;outline-offset:2px}.d-drone-demo button[class*="-inspect"]{display:none!important}.d-drone-demo :where(input){accent-color:#9bb7c8}.d-drone-demo :where(h1,h2,h3,h4,b,strong){font-weight:500}
.d-drone-stage{background:#17242c;border-radius:12px}.d-drone-sky{background:linear-gradient(0deg,#17384466,transparent),url('data:image/webp;base64,') center/cover!important}.d-drone-sky>*{display:none}.d-drone-scroll{padding:22px 16px}.d-drone-scroll h3{font-family:Inter!important;font-size:24px;font-weight:450;line-height:1.1;color:#c0d7e4}.d-drone-scroll p{font-size:12px;color:#819fb2;line-height:1.5}.d-drone-scroll span{font-size:10px;color:#6c91a7}.d-drone-reset{display:none!important}

/* Verified native-width corrections. */
.d-drone-scroll{padding:0!important;left:44%}.d-drone-sky{right:56%}.d-drone-scroll article{padding:17px 13px!important}.d-drone-scroll h3{font-size:21px!important;line-height:1.13!important;overflow-wrap:normal;word-break:normal}.d-drone-scroll em{font-size:9px;color:#7594a8}
